package com.example

/**
 * 10 ශ්‍රේණිය ඉතිහාසය - කාණ්ඩ 17 සිට 20 දක්වා (80 unique cards).
 * 100% curriculum-aligned with official Sri Lankan O/L Grade 10 History Syllabus.
 */
object FlashcardBankHistoryGrade10SetsPart3 {

  fun getCard(setNum: Int, cardNum: Int): CardContentTuple? {
    val c = cardNum.coerceIn(1, 20)
    return when (setNum) {
      17 -> set17KurunegalaGampola[(c - 1) % 20]
      18 -> set18KotteKingdomAndLiterature[(c - 1) % 20]
      19 -> set19MapMarkingAndArchaeology[(c - 1) % 20]
      20 -> set20Grade10FullComprehensive[(c - 1) % 20]
      else -> null
    }
  }

